+        name: 'confirmation',
+        message: 'Do you want to publish these versions?',
+        type: 'confirm',
+      },
+    ]);
+    return reply.confirmation;
+  } catch (e) {
+    // Handle the case where the user exits the prompt with ctrl+c
+    return false;
+  }
